_pixmap_cache = {}

def get_svg_pixmap(name: str, size: int = 16, color: str = "#94a3b8") -> QPixmap:
    cache_key = (name, size, color)
    if cache_key in _pixmap_cache:
        return _pixmap_cache[cache_key]

    raw_svg = SVG_ICONS.get(name, SVG_ICONS["other"])
    colored_svg = raw_svg.replace('stroke="currentColor"', f'stroke="{color}"').replace('fill="currentColor"', f'fill="{color}"')
    
    renderer = QSvgRenderer(QByteArray(colored_svg.encode("utf-8")))
    pixmap = QPixmap(size, size)
    pixmap.fill(QColor(0, 0, 0, 0))  # transparent
    
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    renderer.render(painter)
    painter.end()

    _pixmap_cache[cache_key] = pixmap
    return pixmap

def get_svg_icon(name: str, size: int = 16, color: str = "#94a3b8") -> QIcon:
    return QIcon(get_svg_pixmap(name, size, color))

